Here's a complete example of modern data-driven MSTest tests for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator;

    public PriceCalculatorTests()
    {
        _calculator = new PriceCalculator();
    }

    // --- CalculateTotal: DataRow for simple inline cases ---

    [TestMethod]
    [DataRow(1, 9.99, 9.99, DisplayName = "Single item")]
    [DataRow(5, 10.00, 50.00, DisplayName = "Multiple items")]
    [DataRow(0, 25.00, 0.00, DisplayName = "Zero quantity")]
    [DataRow(1, 0.00, 0.00, DisplayName = "Zero price")]
    [DataRow(3, 33.33, 99.99, DisplayName = "Fractional price")]
    public void CalculateTotal_WithVariousInputs_ReturnsExpected(
        int quantity, double price, double expected)
    {
        var result = _calculator.CalculateTotal(quantity, (decimal)price);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    public void CalculateTotal_NegativeQuantity_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(-1, 10m));
    }

    // --- ApplyDiscount: DynamicData with ValueTuples for complex data ---

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithVariousDiscounts_ReturnsExpected(
        decimal subtotal, int discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(subtotal, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal subtotal, int discountPercent, decimal expected)>
        DiscountTestData =>
    [
        (100m, 10, 90m),
        (200m, 25, 150m),
        (50m,  0,  50m),
        (100m, 100, 0m),
        (0m,   50, 0m),
        (79.99m, 20, 63.992m),
    ];

    [TestMethod]
    public void ApplyDiscount_NegativePercent_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, -5));
    }

    [TestMethod]
    public void ApplyDiscount_Over100Percent_ThrowsArgumentOutOfRange()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, 101));
    }
}
```

**Key patterns used:**

| Pattern | Where | Why |
|---|---|---|
| `[DataRow]` | `CalculateTotal` | Simple inline values; `DisplayName` labels each case |
| `[DynamicData]` + ValueTuples | `ApplyDiscount` | Type-safe `decimal` data (DataRow can't hold `decimal` literals) |
| `Assert.ThrowsExactly<T>` | Negative/edge cases | Modern replacement for `[ExpectedException]` — also lets you inspect the exception |
| `sealed` class | Class declaration | Performance + design clarity (MSTest best practice) |
| Constructor init | `_calculator` | Enables `readonly`, works with nullability analysis |

**DataRow vs DynamicData rule of thumb:**
- **`[DataRow]`** — great for `int`, `double`, `string`, `bool` (attribute-compatible types)
- **`[DynamicData]` with ValueTuples** — required for `decimal`, complex objects, or when you need more than ~5 parameters

Adjust the exception types and rounding logic to match your actual `PriceCalculator` implementation.
